import{_ as o,o as t,c as p,a5 as l}from"./chunks/framework.BPFk9-tb.js";const _=JSON.parse('{"title":"写作课作业-088","description":"","frontmatter":{"date":"2020-10-22T19:37:49","title":"写作课作业-088","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/088.md","filePath":"posts/homework/088.md"}'),a={name:"posts/homework/088.md"};function r(c,e,i,s,n,u){return t(),p("div",null,[...e[0]||(e[0]=[l('<blockquote><p>《微信互联网平民创业》之《20.你如何才能快速融入社区?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>在这里，对平民来说更为重要的是：</p><ul><li>我如何才能快速融入社群？</li><li>我如何才能真正快速成长？</li></ul></blockquote><blockquote><p>如何选择社群？</p><p>它的长期价值是什么？这个问题大答案将帮助你权衡你是否应更加入某个社群？</p></blockquote><blockquote><p>融入社群的方式就异常清楚了：在社群认同的价值观方向上迅速成长……</p></blockquote><blockquote><p>在「社群认同的价值观方向上不断成长」之外，在做一件事儿，你就不仅已经「融入了社群」，更会成为社群的「中坚力量」：</p><p>乐于分享。</p><p>因为乐于分享才逐步变成了第一」—— 因为乐于分享，所以，此人获得了一个 更为全面的堪比「上帝视⻆」的理解环境......</p></blockquote><blockquote><p>最好实名，对建立「个人品牌」的帮助非常大</p></blockquote><blockquote><p>融入好的社群就是最简单直接粗暴有效的社交</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>自己加入了且慢写作群，长期持续的写作就是这个社群的价值观。如果没有写就无法融入到这个社群当中，自己因为一些原因，写作断了一段时间，就连在群里发言也少了，可以说是自己没有养成长期的观念，也可以说是自己没有融入到这个社群当中，不仅没有融入，而且是被远远的甩在了后面。</p><p>反而看着的别人成长自己还很痛苦，但正是因为这样的痛苦——「你每天健康那么多人为了自己的进步挣扎，自己“坚持”不挣扎」，事实上是很难的！」——正确的痛苦，让我在有时间的时候补作业。</p><p>或许自己没有做到第一的经验，或许是自己的性格问题，在落后之后就变得默不作声，如果说得好听一点，写作就像是一个人的奥德赛，但这样的方式不利于自己的成长，因为即使有成长也很慢。另外有这么好的社群不用起来自己就是傻呀。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',19)])])}const d=o(a,[["render",r]]);export{_ as __pageData,d as default};
